import {COURSES,SUBJECT_GROUPS,courseById,courseForDomain} from './catalog.mjs';
import {AUTHORED_QUESTIONS,TOPICS,topicsForCourse,practiceInfo} from './engine.mjs';
import {practiceSourceSummary,practiceSourceView} from './practice-context.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const option=(rows,value)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(label)}</option>`).join('');
const date=s=>new Date(s).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric',timeZone:'Asia/Seoul'});

export function renderPracticeView({ui,data={},sessions={}}){
 const course=courseById(ui.courseId)||courseForDomain(ui.subject)||COURSES[0],applied=ui.practiceMode==='applied',mode=applied?'applied':'standard';
 const topics=topicsForCourse(course.id).filter(t=>!applied||practiceInfo(course.id,t.id,mode).bankCount);
 if(ui.topic!=='mixed'&&!topics.some(t=>t.id===ui.topic))ui.topic='mixed';
 const info=practiceInfo(course.id,ui.topic,mode);if(!info.counts.includes(ui.count))ui.count=info.dynamic?5:info.bankCount;
 const recent=Object.values(sessions).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,4),summary=practiceSourceSummary(data,course.id,ui.topic,mode);
 const previews=applied?AUTHORED_QUESTIONS.filter(q=>q.practiceSet==='type-linked'&&q.courseId===course.id&&(ui.topic==='mixed'||q.topicId===ui.topic)):[];
 return `<div class="page-heading"><div><div class="eyebrow">PRACTICE MAKER</div><h1>기출의 개념을, 새로운 조건에 적용해요.</h1><p>전 과목의 응용문제와 풀이를 확인하고, 연결된 기출 유형으로 돌아가 비교하세요.</p></div></div><div class="practice-layout linked-practice-layout"><div><section class="card builder"><h2>나에게 맞는 예상·연습문제</h2><div class="field"><div class="field-label">연습 구성</div><div class="practice-mode-options">${[['applied','기출 유형 연결 응용','새로운 상황과 조건을 해석하는 등록 문항'],['standard','기본 연습·유형 변형','개념 문제 또는 수치·제한된 지문 틀 변형']].map(([id,title,description])=>`<button class="practice-mode ${mode===id?'active':''}" data-action="practice-mode" data-mode="${id}" aria-pressed="${mode===id}"><strong>${title}</strong><span>${description}</span></button>`).join('')}</div></div><div class="field"><div class="field-label">영역</div><div class="subject-options domain-options">${SUBJECT_GROUPS.map(g=>`<button class="subject-option ${course.domain===g.id?'active':''}" data-action="practice-subject" data-subject="${esc(g.id)}">${esc(g.id)}</button>`).join('')}</div></div><div class="field"><label for="practice-course">세부 과목</label><select id="practice-course">${option(COURSES.filter(c=>c.domain===course.domain).map(c=>[c.id,c.label]),course.id)}</select></div><div class="field"><label for="practice-topic">연습할 유형</label><select id="practice-topic">${option([['mixed','여러 개념 골고루'],...topics.map(t=>[t.id,t.label])],ui.topic)}</select></div><div class="field-row"><div class="field"><div class="field-label">학습 단계</div>${applied?'<p class="practice-stage">응용 · 조건과 사례에 적용</p>':`<div class="choice-group">${(course.id==='math-common'?[1,2,3]:[1]).map(n=>`<button class="choice-btn ${course.id!=='math-common'||ui.level===n?'active':''}" data-action="level" data-level="${n}">${['기본','응용','심화'][n-1]}</button>`).join('')}</div>`}</div><div class="field"><div class="field-label">문제 수</div><div class="choice-group">${info.counts.map(n=>`<button class="choice-btn ${ui.count===n?'active':''}" data-action="count" data-count="${n}">${n}문항</button>`).join('')}</div></div></div><div class="notice"><div>${applied?`선택한 범위의 자체 응용문제 ${info.bankCount}문항에서 겹치지 않게 묶습니다. 보기 순서만 바꾸어 새 문항으로 세지 않습니다.`:info.dynamic?`${course.domain==='수학'?'수치와 식을 변형해 풀이 원리를 연습합니다.':'자체 작성한 제한된 독해 지문 틀을 변형합니다. 내용이 유사할 수 있습니다.'}`:`선택한 범위에 등록된 자체 연습 ${info.bankCount}문항을 중복 없이 묶습니다.`}</div></div><button class="btn primary full" data-action="generate" ${!ui.count?'disabled':''}>${applied?'응용문제':info.dynamic?'유형 변형':'연습문제'} ${ui.count}문항 ${info.dynamic?'만들기':'시작하기'}</button><div class="below"><button class="btn ghost small" data-action="course-archive" data-course="${esc(course.id)}">${esc(course.label)} 공식 기출 원문</button></div><p class="footnote">학습 단계는 학습용 분류이며 수능 난도나 출제 확률을 추정한 값이 아닙니다.</p></section>${previews.length?`<section class="card practice-preview"><h2>이번 범위의 응용문제</h2><p>단계별 풀이·선택지별 오답 해석${course.domain==='영어'||course.domain==='제2외국어/한문'?'·전체 해석·핵심 어휘를 제공합니다.':'을 제공합니다.'}</p>${previews.map(q=>`<article><span class="meta">${esc(q.topic)} · 자체 구성</span><h3>${esc(q.statement)}</h3><button class="btn small" data-action="open-question" data-id="${esc(q.id)}">이 문제 풀기</button></article>`).join('')}</section>`:''}</div><aside>${practiceSourceView(summary)}<section class="card recent-sessions"><h3>최근 학습 묶음</h3>${recent.length?recent.map(s=>`<div class="session-row"><div><strong>${esc(s.courseName||s.subject)} · ${s.questionIds.length}문항</strong><p>${date(s.createdAt)} · ${s.practiceMode==='applied'?'기출 유형 연결 응용':esc(TOPICS.find(t=>t.id===s.topicId)?.label||'여러 개념')}</p></div><button class="btn small" data-action="resume" data-id="${esc(s.id)}">이어서 풀기</button></div>`).join(''):'<p class="footnote">문제 묶음을 시작하면 여기에 표시됩니다.</p>'}</section></aside></div>`;
}
